  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * 1. Summary: Calculates the final price for a booking considering a 20% discount if the customer has a membership package with DISCOUNTS award and the booking is made at least 24 hours before departure. Returns price with one decimal place.
   * 2. Algorithm:
   *    if (customer == null OR customer.membershipPackage == null) return this.price;
   *    if (!customer.membershipPackage.hasAward(Award.DISCOUNTS)) return this.price;
   *    if (bookingTime == null) return this.price;
   *    // Check if bookingTime is at least 24 hours before departureTime
   *    if (departureTime - bookingTime >= 24 hours) {
   *        discountedPrice = this.price * 0.8;
   *        return Math.round(discountedPrice * 10) / 10.0; // keep one decimal
   *    }
   *    return this.price;
   * 3. Related Features: price, departureTime, Customer::membershipPackage
   * 4. Related Classes: Customer, MembershipPackage, Award
   * 5. Input: customer : Customer, bookingTime : String - format "yyyy-MM-dd HH:mm"
   * 6. Output: double - final price with one decimal place.
   * 7. Pre-condition: Trip exists.
   * 8. Post-condition: No change to system state.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || customer.getMembershipPackage() == null) {
      return this.price;
    }
    if (!customer.getMembershipPackage().hasAward(Award.DISCOUNTS)) {
      return this.price;
    }
    if (bookingTime == null) {
      return this.price;
    }
    try {
      SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm");
      Date bookingDate = sdf.parse(bookingTime);
      Date departureDate = sdf.parse(this.departureTime);
      long diffInMillis = departureDate.getTime() - bookingDate.getTime();
      long twentyFourHoursInMillis = 24 * 60 * 60 * 1000L;
      if (diffInMillis >= twentyFourHoursInMillis) {
        double discountedPrice = this.price * 0.8;
        return Math.round(discountedPrice * 10) / 10.0;
      }
    } catch (ParseException e) {
      return this.price;
    }
    return this.price;
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Computes the reward points earned by a customer during a given month. Only customers whose membership package contains the POINTS award are eligible. Only bookings whose booking date falls inside the requested month shall be counted. Each booked seat contributes 5 points. Invalid inputs, missing membership packages, or unsupported rewards shall return 0.
   * Algorithm:
   * Related Features: bookings, membershipPackage, numberOfSeats
   * Related Classes: Customer, MembershipPackage, Award, Booking
   * Input: customer : Customer, currentMonth : String - format "yyyy-MM"
   * Output: int - total reward points (>= 0).
   * Pre-condition: Customer exists.
   * Post-condition: No change to system state.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || customer.getMembershipPackage() == null) {
      return 0;
    }
    if (!customer.getMembershipPackage().hasAward(Award.POINTS)) {
      return 0;
    }
    if (currentMonth == null) {
      return 0;
    }
    int totalPoints = 0;
    for (Booking booking : this.getBookings()) {
      if (booking.isInMonth(currentMonth)) {
        totalPoints += booking.getNumberOfSeats() * 5;
      }
    }
    return totalPoints;
  }

